import pytest
import click
from click.testing import CliRunner

def test_runner_catch_exceptions_on_runner():
    @click.command()
    def cli():
        raise ValueError("This is an error")

    runner = CliRunner(catch_exceptions=False)
    result = runner.invoke(cli)
    assert isinstance(result.exception, ValueError)

import os
import pytest
from click.testing import CliRunner
from click import Command, Group, option


@pytest.fixture
def runner():
    return CliRunner()


def test_fish_completion_multiline_help(runner):
    @Group()
    def cli():
        pass

    @cli.command()
    @option(
        "attachment_types",
        "--at",
        "--attachment-type",
        type=(str, str),
        multiple=True,
        help="\b\nAttachment with explicit mimetype,\n--at image.jpg image/jpeg",
    )
    def subcmd(attachment_types):
        pass

    # Simulate fish completion environment
    env = {
        "_CLI_COMPLETE": "fish_complete",
        "COMP_WORDS": "cli subcmd --",
        "COMP_CWORD": "--",
    }

    result = runner.invoke(cli, ["--completion", "fish"], env=env)

    # The bug causes a fish shell error due to unescaped newlines in help text.
    # The fix should ensure that the help text is properly escaped or handled
    # so that the completion output is valid.
    # We expect the completion output to contain the option without causing a shell error.
    # The specific format for fish completion is "plain,<option_name>\t<help_text>".
    # The help text should be on a single line, with newlines replaced by spaces or removed.
    assert "plain,--at\tAttachment with explicit mimetype, --at image.jpg image/jpeg" in result.output

import pytest
import click
from click.testing import CliRunner


class MyClass:
    def __init__(self, myvalue: str) -> None:
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_value: str) -> "MyClass":
        if input_value != "works":
            raise ValueError(f"input was {input_value!r}, should be 'works'")
        return MyClass(input_value)


@pytest.fixture
def runner():
    return CliRunner()


def test_func_param_type_value_error_message(runner):
    @click.command()
    @click.argument("mydata", type=click.types.FuncParamType(MyClass.from_str))
    def cli(mydata):
        pass

    result = runner.invoke(cli, ["fails"])
    assert "Error: input was 'fails', should be 'works'" in result.output
